import pandas as pd
import numpy as np
import yfinance as yf

# Define the strategy parameters
class MomentumStrategy:
    def __init__(self, symbol, period):
        self.symbol = symbol
        self.period = period
        self.data = yf.download(symbol, period=period)

        # Calculate the indicators
        self.data['ATR'] = self.calculate_atr(self.data['High'], self.data['Low'], self.data['Close'])
        self.data['Parabolic SAR'] = self.calculate_parabolic_sar(self.data['High'], self.data['Low'])
        self.data['Ichimoku'] = self.calculate_ichimoku(self.data['High'], self.data['Low'])
        self.data['CCI'] = self.calculate_cci(self.data['Close'])

    def calculate_atr(self, high, low, close):
        high_low = high - low
        high_close = (high - close.shift(1)).abs()
        low_close = (low - close.shift(1)).abs()
        ranges = pd.concat([high_low, high_close, low_close], axis=1)
        true_range = ranges.max(axis=1)
        atr = true_range.ewm(span=14, adjust=False).mean()
        return atr

    def calculate_parabolic_sar(self, high, low):
        sar = pd.Series(0, index=high.index)
        sar[0] = low[0]
        acceleration = 0.02
        maximum = 0.2
        long = False
        short = False
        for i in range(1, len(sar)):
            if long:
                sar[i] = sar[i-1] + acceleration * (high[i-1] - sar[i-1])
                if sar[i] > high[i-1]:
                    sar[i] = high[i-1]
                if low[i-1] < sar[i]:
                    long = False
                    short = True
                    sar[i] = low[i-1]
            elif short:
                sar[i] = sar[i-1] - acceleration * (sar[i-1] - low[i-1])
                if sar[i] < low[i-1]:
                    sar[i] = low[i-1]
                if high[i-1] > sar[i]:
                    short = False
                    long = True
                    sar[i] = high[i-1]
            else:
                sar[i] = low[0]
        return sar

    def calculate_ichimoku(self, high, low):
        conversion_line = (high.rolling(window=9).max() + low.rolling(window=9).min()) / 2
        base_line = (high.rolling(window=26).max() + low.rolling(window=26).min()) / 2
        leading_span_A = (conversion_line + base_line) / 2
        leading_span_B = (high.rolling(window=52).max() + low.rolling(window=52).min()) / 2
        ichimoku = pd.DataFrame({'conversion_line': conversion_line, 'base_line': base_line, 'leading_span_A': leading_span_A, 'leading_span_B': leading_span_B})
        return ichimoku

    def calculate_cci(self, close):
        cci = (close - close.rolling(window=14).mean()) / (close.rolling(window=14).std() * 0.015)
        return cci

    def generate_signals(self):
        signals = pd.DataFrame(index=self.data.index)
        signals['long'] = (self.data['Parabolic SAR'] < self.data['Low']) & (self.data['CCI'] > 100) & (self.data['Ichimoku']['leading_span_A'] > self.data['Ichimoku']['leading_span_B'])
        signals['short'] = (self.data['Parabolic SAR'] > self.data['High']) & (self.data['CCI'] < -100) & (self.data['Ichimoku']['leading_span_A'] < self.data['Ichimoku']['leading_span_B'])
        return signals

    def calculate_position_size(self, account_balance):
        position_size = account_balance * 0.02
        return position_size

